        for line in handle:
            fields = line.strip().split(",")
            orders.append({"id": fields[0], "amount": float(fields[1]), "status": fields[2]})
    return orders


def total_paid(orders):
    total = 0
    for order in orders:
        if order["status"] == "paid":
            total = total + order["amount"]
    return total


def overdue_ids(orders, today, due_days=30):
    result = []
    for order in orders:
        if order["status"] != "paid" and (today - order["created"]).days > due_days:
            result.append(order["id"])
    return result
